import{z as o,x as B,o as l,c as d,q as t,j as s,D as e,d as r,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"评分细则奖励","description":"","frontmatter":{"title":"评分细则奖励","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rubric-reward.md","filePath":"llm/rubric-reward.md","lastUpdated":1791063341000}'),m={name:"llm/rubric-reward.md"};function p(u,a,h,D,_,c){const A=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=t('<h1 id="评分细则奖励" tabindex="-1">评分细则奖励 <a class="header-anchor" href="#评分细则奖励" aria-label="Permalink to &quot;评分细则奖励&quot;">​</a></h1><div class="epigraph"><p>先把「好」拆成可独立打分的条目，再加权；印象分里的冗长与客气就不再独占标量。</p><footer>—— 对照细粒度 RLHF（Wu 等）把偏好拆成维度；产品侧的书面规范则把条目写成可执行检查单</footer></div><p><a href="/llm/llm-judge-reward">上一课</a>的裁判给出整体胜负，位置与冗长偏爱直接进 \\(r\\)。缺口是：<strong>一个标量无法说出「事实对但语气差」还是「语气好但编造」。</strong> 评分细则（rubric）把质量写成若干条可判定或可打分的检查项，再合成奖励。Llama 2 已经把有用与安全拆成两个 <a href="/llm/reward-model">RM</a>；本课把拆分推进到条目级。后课代码 / 数学验证器是细则里「可程序化」的极限。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放域的「好」是多维的：正确、完整、安全、格式、引用。整体比较强迫标注员当场权衡，残差进 BT。细则要求事先写权衡：每条独立标，合成规则由产品定，而不是由标注员的即时口味定。Wu 等人的细粒度 RLHF 把人类反馈对准密度更高的片段与类型（相关性、事实、信息量），而不是整段一个分。</p><p>条目若仍由 LLM 裁判打，只是把偏差从一维拆到多维：每条仍可能爱长。条目若可程序化（是否含引用、是否拒答、单测是否过），那一部分离开裁判。本课的对象是混合：能写进检查单的写进检查单，剩下的才用模型打。</p><p><span class="marginnote">「评分细则」就是老师批作文用的那张评分表：不问「这篇整体好不好」，而是逐项问「论点有没有、错别字多不多、卷面整不整洁」，每项单独给分再加总。LLM 训练里就是把这评分表交给程序或模型来逐项打分。</span></p><h3 id="细则是合同-不是提示装饰" tabindex="-1">细则是合同，不是提示装饰 <a class="header-anchor" href="#细则是合同-不是提示装饰" aria-label="Permalink to &quot;细则是合同，不是提示装饰&quot;">​</a></h3><p>同一套条目必须用于标注指南、裁判提示、合成公式与评测报告。训练用「正确 0.7 + 文风 0.3」，评测却只报整体 Arena，细则没有约束力。权重改动等于改任务，要版本号。</p><p><span class="marginnote">条目过多则标注员与裁判都不稳。宁可 5 条定义清楚，不要 20 条互相包含。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：列出互斥尽量干净的条目 \\(c_1,\\ldots,c_m\\)，每条取值 \\(\\{0,1\\}\\) 或有限李克特。合成</p> \\[r(x,y)=\\sum_{m} w_m\\, c_m(x,y),\\qquad \\sum_m w_m=1 \\]<p>或先硬约束（安全 \\(c_{\\mathrm{safe}}=0\\) 则 \\(r\\) 封顶为负）再对有用加权。\\(c_m\\) 的实现可以是：程序、专用分类头、或带条目定义的 LLM 裁判。接到 <a href="/llm/ppo-llm">PPO</a> 的仍是标量；差别是标量的构成可审计。多目标 Pareto 留到后课加权。</p>',14)),(l(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%AE%8C%E6%88%90%20y%22%5D%20--%3E%20C1%5B%22%E6%9D%A1%E7%9B%AE%EF%BC%9A%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20Y%20--%3E%20C2%5B%22%E6%9D%A1%E7%9B%AE%EF%BC%9A%E5%AE%89%E5%85%A8%22%5D%0A%20%20Y%20--%3E%20C3%5B%22%E6%9D%A1%E7%9B%AE%EF%BC%9A%E6%A0%BC%E5%BC%8F%20%2F%20%E5%BC%95%E7%94%A8%22%5D%0A%20%20C1%20--%3E%20W%5B%22%E5%8A%A0%E6%9D%83%E6%88%96%E7%A1%AC%E9%97%A8%22%5D%0A%20%20C2%20--%3E%20W%0A%20%20C3%20--%3E%20W%0A%20%20W%20--%3E%20R%5B%22%E6%A0%87%E9%87%8F%20r%22%5D%0A%20%20R%20--%3E%20PPO%5B%22PPO%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[r("与 "),E("a",{href:"/llm/process-supervision"},"过程监督"),r(" 的差别：PRM 按推理步骤切；细则按质量轴切。一道数学题可以同时有步骤对错与「解释是否可读」两条，不要合成一个头。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：设权重为「正确 0.7、简洁 0.3」。回答 A 事实全对但啰嗦，得 \\(c_{\\text{正确}}=1\\)、\\(c_{\\text{简洁}}=0\\)，则 \\(r=0.7\\)；回答 B 又对又干脆，\\(r=1.0\\)。整体打分时两者可能只差半颗星，条目化之后差距从哪来一目了然。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"拆分改变梯度来源：策略不能再用单一捷径同时抬所有 \\(c_m\\)。拉长可以抬「完整」，同时被「简洁」条目扣分，冲突被显式化。硬门把安全从权衡里拿出去，避免有用 RM 把拒答当成低分。这正是 Llama 2 分头的理由，细则是同一逻辑的更细网格。",-1)),(l(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%AD%96%E7%95%A5%E5%AD%A6%E5%88%B0%E6%8D%B7%E5%BE%84%EF%BC%9A%E6%8A%8A%E5%9B%9E%E7%AD%94%E6%8B%89%E9%95%BF%22%5D%20--%3E%20A%5B%22%E5%AE%8C%E6%95%B4%E6%80%A7%E6%9D%A1%E7%9B%AE%EF%BC%9A%E5%8A%A0%E5%88%86%22%5D%0A%20%20P%20--%3E%20B%5B%22%E7%AE%80%E6%B4%81%E6%80%A7%E6%9D%A1%E7%9B%AE%EF%BC%9A%E6%89%A3%E5%88%86%22%5D%0A%20%20A%20--%3E%20N%5B%22%E4%B8%A4%E7%9B%B8%E6%8A%B5%E6%B6%88%EF%BC%8C%E5%87%80%E6%94%B6%E7%9B%8A%E8%B6%8B%E9%9B%B6%22%5D%0A%20%20B%20--%3E%20N%0A%20%20P%20--%3E%20S%5B%22%E5%9B%9E%E7%AD%94%E5%A4%B9%E5%B8%A6%E6%9C%89%E5%AE%B3%E5%86%85%E5%AE%B9%22%5D%0A%20%20S%20--%3E%20G%5B%22%E5%AE%89%E5%85%A8%E7%A1%AC%E9%97%A8%E8%A7%A6%E5%8F%91%EF%BC%9Ar%20%E5%B0%81%E9%A1%B6%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20G%20--%3E%20X%5B%22%E5%86%8D%E6%9C%89%E7%94%A8%E4%B9%9F%E4%B8%8D%E6%94%BE%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">常见误区：以为条目越多越准。「有用」与「信息量」高度相关的两条若各占 0.3 权重，等于把同一维度重复计了 0.6，别的轴被挤掉——这就是正文说的双重计数，所以要先看相关矩阵再合并共线条目。</span></p><p><span class="marginnote">权重 \\(w\\) 是产品决策。数据科学家在验证集上扫 \\(w\\)，等于在扫任务，应与业务一起锁，而不是当超参默默改。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>条目之间的相关会让加权双重计数。先看条目相关矩阵，合并共线项。可程序化条目应尽快变成下一课的验证器，减少裁判噪声。开放轴（幽默、品味）细则写不清，仍会退回整体比较。合成后的 \\(r\\) 仍会过优化，只是黑客要从多条同时骗。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>细则把「好」拆成条目再加权或硬门，减少整体印象分的捷径垄断。</li><li>同一合同要贯穿标注、裁判、训练与评测。</li><li>可程序化条目应交给验证器；模型只打剩下的轴。</li><li>加权是改任务，必须版本化。</li><li>出处：Wu 等 Fine-Grained RLHF；Llama 2 有用/安全分头；裁判偏差见 Zheng 等。</li></ul>',6))])}const P=o(m,[["render",p]]);export{f as __pageData,P as default};
